/* Proview Menu – Setup: Marketplace + Settings (inventory §5) */
(function(){
const {UI,$,$$}=App;const {ic,esc,uid,initials}=UI;const S=App.state;
S.cfg=S.cfg||{};S.tables=S.tables||[];S.areas=S.areas||['No Area'];S.staff=S.staff||[];S.connected=S.connected||[];S.floor=S.floor||[];
const v=(k,d)=>S.cfg[k]!==undefined?S.cfg[k]:d;
const A=(n,f)=>App.action('set-'+n,f);
const GU=o=>App.guestUrl?App.guestUrl(o||{}):'';
const nowStr=()=>{const d=new Date();return `08/11/2026 ${String(d.getHours()).padStart(2,'0')}:${String(d.getMinutes()).padStart(2,'0')}`};

/* ---------- local form helpers (data-k = persisted key) ---------- */
const inp=(k,d='',ph='',o={})=>UI.input({value:v(k,d),placeholder:ph,type:o.type||'text',prefix:o.prefix||'',suffix:o.suffix||'',attrs:`data-k="${k}" ${o.attrs||''}`});
const ta=(k,d='',ph='',rows=3)=>UI.textarea({value:v(k,d),placeholder:ph,rows,attrs:`data-k="${k}"`});
const sel=(k,opts,d,attrs='')=>UI.select(opts,v(k,d),`data-k="${k}" ${attrs}`);
const tg=(k,d=false,attrs='')=>UI.toggle(v(k,d),`data-k="${k}" ${attrs}`);
const ck=(k,label,d=false,attrs='')=>UI.check(label,v(k,d),`data-k="${k}" ${attrs}`);
const color=(k,d,attrs='')=>`<div style="display:flex;gap:8px;align-items:center"><input type="color" value="${v(k,d)}" data-k="${k}" ${attrs} style="width:44px;height:40px;border:1px solid var(--border-input);border-radius:8px;padding:2px;background:#fff;cursor:pointer" aria-label="Colour"><code class="muted" data-hex="${k}">${v(k,d)}</code></div>`;
const rc=(k,opts,d,attrs='')=>{const val=v(k,d);return `<div class="radio-cards">${opts.map(o=>`<label class="radio-card"><input type="radio" name="${k}" value="${esc(o.value)}" data-k="${k}" ${o.value===val?'checked':''} ${attrs}><div><strong>${o.label}${o.tag?` <span class="pill grey" style="height:20px">${o.tag}</span>`:''}</strong>${o.text?`<small>${o.text}</small>`:''}</div></label>`).join('')}</div>`};
const radios=(k,opts,d,attrs='')=>{const val=v(k,d);return `<div style="display:flex;gap:18px;flex-wrap:wrap">${opts.map(o=>`<label class="check"><input type="radio" name="${k}" value="${esc(o)}" data-k="${k}" ${o===val?'checked':''} ${attrs} style="accent-color:var(--brand-700)">${o}</label>`).join('')}</div>`};
/* toggle row that reveals a sub-block */
const trow=(k,title,text='',d=false,sub='',extra='')=>`<div class="form-row" style="flex-wrap:wrap"><div class="txt"><strong>${title}</strong>${text?`<small>${text}</small>`:''}${extra}</div>${tg(k,d,sub?`data-change="set-reveal" data-reveal="rv-${k.replace(/\W/g,'_')}"`:'')}${sub?`<div id="rv-${k.replace(/\W/g,'_')}" style="flex-basis:100%;margin-top:12px" ${v(k,d)?'':'hidden'}>${sub}</div>`:''}</div>`;
const newTag='<span class="tag-new">New</span>';
const saveBtn=(act='set-save')=>`<div style="display:flex;justify-content:flex-end;margin-top:20px"><button class="btn primary" data-action="${act}">Save</button></div>`;
const g2=(...f)=>`<div class="grid g2" style="gap:0 16px">${f.join('')}</div>`;
const F=(label,control,o={})=>UI.field({label,control,...o});
const h3=(t,sub='')=>`<h3 style="margin:4px 0 ${sub?'2px':'12px'}">${t}</h3>${sub?`<p class="muted" style="margin:0 0 12px">${sub}</p>`:''}`;

A('reveal',el=>{const b=document.getElementById(el.dataset.reveal);if(b)b.hidden=!el.checked});
A('save',()=>{collect();App.toast('Settings saved')});
function collect(){
  $$('#view [data-k]').forEach(el=>{const k=el.dataset.k;let val;
    if(el.type==='checkbox')val=el.checked;else if(el.type==='radio'){if(!el.checked)return;val=el.value}else if(el.type==='file')return;else val=el.value;
    S.cfg[k]=val;if(k.startsWith('venue.'))S.venue[k.slice(6)]=val});
  if(S.venue?.name){const n=$('#venueName');if(n)n.textContent=S.venue.name}
}
document.addEventListener('input',e=>{const h=e.target.dataset&&e.target.type==='color'&&document.querySelector(`[data-hex="${e.target.dataset.k}"]`);if(h)h.textContent=e.target.value});

/* ---------- lists ---------- */
const COUNTRIES=['United Kingdom of Great Britain and Northern Ireland','Ireland','France','Germany','Spain','Italy','Portugal','Netherlands','Belgium','Switzerland','Austria','Sweden','Norway','Denmark','Finland','Poland','Greece','Türkiye','Cyprus','Malta','United States of America','Canada','Australia','New Zealand','United Arab Emirates','Saudi Arabia','Qatar','Kuwait','Bahrain','Oman','Egypt','Morocco','South Africa','India','Pakistan','Singapore','Malaysia','Japan','South Korea','Brazil','Mexico'];
const TZ=['Europe/London','Europe/Dublin','Europe/Paris','Europe/Berlin','Europe/Madrid','Europe/Rome','Europe/Amsterdam','Europe/Istanbul','Europe/Athens','Asia/Dubai','Asia/Riyadh','Asia/Qatar','Asia/Kuwait','Asia/Kolkata','Asia/Singapore','Asia/Tokyo','America/New_York','America/Chicago','America/Los_Angeles','America/Toronto','Australia/Sydney','Pacific/Auckland'];
const LANGS=['English','Turkish','Arabic','French','German','Spanish','Italian','Portuguese','Russian','Polish','Greek','Dutch','Chinese','Japanese','Korean','Hindi','Urdu','Persian','Romanian','Bulgarian'];
const CURR=[['GBP','British Pound Sterling'],['EUR','Euro'],['USD','US Dollar'],['TRY','Turkish Lira'],['AED','UAE Dirham'],['SAR','Saudi Riyal'],['QAR','Qatari Riyal'],['KWD','Kuwaiti Dinar'],['BHD','Bahraini Dinar'],['OMR','Omani Rial'],['AUD','Australian Dollar'],['CAD','Canadian Dollar'],['NZD','New Zealand Dollar'],['CHF','Swiss Franc'],['SEK','Swedish Krona'],['NOK','Norwegian Krone'],['DKK','Danish Krone'],['PLN','Polish Zloty'],['JPY','Japanese Yen'],['INR','Indian Rupee'],['EGP','Egyptian Pound'],['ZAR','South African Rand'],['SGD','Singapore Dollar']];

/* =========================================================
   MARKETPLACE (§5.1)
   ========================================================= */
const slug=n=>n.toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'');
function allInts(){const I=S.integrations;return [
  ['Payment Providers','payment',I.payment],['POS Providers','pos',I.pos],['Printer Providers','printer',I.printer],['Accessibility Providers','access',I.access]].map(([t,k,l])=>({title:t,key:k,list:l.map(([name,cat,price])=>({name,cat,price,group:k}))}))}
const findInt=s=>allInts().flatMap(g=>g.list).find(i=>slug(i.name)===slug(decodeURIComponent(s||"")));
const isConn=n=>S.connected.some(c=>c.name===n);
let mpF='all',mpQ='';

App.route('marketplace',()=>UI.pageHead({title:'Marketplace',sub:'Connect and manage integrations for your restaurant'})+
  UI.hubCards([{icon:'blocks',title:'My Integrations',text:'View and manage your connected integrations',href:'marketplace-my'},{icon:'cart',title:'All Integrations',text:'Browse and connect new integrations',href:'marketplace-all'}],2).replace('class="hub"','class="hub" style="max-width:640px;grid-template-columns:repeat(2,minmax(0,1fr))"'),{nav:'marketplace'});

const mpTabs=a=>UI.tabs([{key:'my',label:'My Integrations',href:'marketplace-my'},{key:'all',label:'All Integrations',href:'marketplace-all'}],a);
App.route('marketplace-all',()=>{const gs=allInts();const counts={all:gs.reduce((a,g)=>a+g.list.length,0),pos:gs[1].list.length,printer:gs[2].list.length,payment:gs[0].list.length,access:gs[3].list.length};
  return UI.pageHead({title:'Marketplace',back:'marketplace',learn:true})+mpTabs('all')+
  `<div class="toolbar"><div style="display:flex;gap:8px;flex-wrap:wrap">${[['all','ALL'],['pos','POS'],['printer','Printer'],['payment','Payment'],['access','Accessibility']].map(([k,l])=>`<button class="chip-btn ${mpF===k?'on':''}" data-action="set-mp-filter" data-f="${k}">${l} (${counts[k]})</button>`).join('')}</div><span class="grow"></span>${UI.searchBox('Search integrations',`data-input="set-mp-search" value="${esc(mpQ)}"`)}</div><div id="mpGrid">${mpGrid()}</div>`},{nav:'marketplace'});
function mpGrid(){const q=mpQ.toLowerCase();const gs=allInts().filter(g=>mpF==='all'||g.key===mpF).map(g=>({...g,list:g.list.filter(i=>i.name.toLowerCase().includes(q)||i.cat.toLowerCase().includes(q))})).filter(g=>g.list.length);
  if(!gs.length)return `<div class="card">${UI.empty('search','No integrations found','Try a different search or filter.')}</div>`;
  return gs.map(g=>`<div class="section-label" style="margin-top:8px">${g.title}</div><div class="grid g4" style="margin-bottom:24px">${g.list.map(i=>`<a class="card pad" href="#marketplace-detail--${slug(i.name)}" style="display:flex;gap:12px;align-items:center;text-decoration:none;color:inherit">
    <span class="itile" style="font-weight:700">${initials(i.name)}</span><div style="min-width:0;flex:1"><strong style="color:var(--ink);display:block">${esc(i.name)}</strong><small class="muted">${esc(i.cat)}</small><div style="margin-top:6px;display:flex;gap:6px;flex-wrap:wrap">${UI.pill(i.price,i.price==='Free'?'ok':'')}${isConn(i.name)?UI.pill('Connected'):''}</div></div></a>`).join('')}</div>`).join('')}
A('mp-filter',el=>{mpF=el.dataset.f;$$('[data-action="set-mp-filter"]').forEach(b=>b.classList.toggle('on',b===el));$('#mpGrid').innerHTML=mpGrid()});
A('mp-search',el=>{mpQ=el.value;$('#mpGrid').innerHTML=mpGrid()});

App.route('marketplace-detail',p=>{const i=findInt(p);if(!i)return UI.pageHead({title:'Integration',back:'marketplace-all'})+`<div class="card">${UI.empty('info','Integration not found')}</div>`;
  const c=isConn(i.name);const regions={payment:['GB','IE','FR','DE','ES','IT','NL','TR','AE','SA','US'],pos:['GB','IE','US','CA','AE','SA','TR'],printer:['GB','IE','TR','AE','US'],access:['GB','IE','TR','US','DE']}[i.group];
  const about={payment:`Take card, Apple Pay and Google Pay payments through ${esc(i.name)} when guests order and pay from your QR menu, pick-up or delivery menu. Payouts go straight to your ${esc(i.name)} account.`,pos:`Send QR, tablet and online orders from Proview straight into ${esc(i.name)}, and keep your menu, prices and availability in sync from your POS.`,printer:'Print kitchen and bar tickets automatically on your receipt printer the moment an order comes in.',access:`${esc(i.name)} adds accessibility tools to your guest menu, such as larger text, high contrast and a screen reader mode.`}[i.group];
  return `<div class="page-head"><div style="display:flex;align-items:center;gap:12px"><a href="#marketplace-all" class="iconbtn" aria-label="Back">${ic('back')}</a><span class="itile" style="width:52px;height:52px;font-weight:700;font-size:18px">${initials(i.name)}</span><div><h2 class="ent-name" style="font-size:18px;line-height:26px;margin:0">${esc(i.name)}</h2><p class="sub">${esc(i.cat)} · ${esc(i.price)}${c?' · '+UI.pill('Connected','ok'):''}</p></div></div>
   <div class="actions"><button class="btn secondary" data-action="set-mp-site" data-n="${esc(i.name)}">${ic('open','sm')}Go to Website</button>${c?`<button class="btn danger" data-action="set-mp-disconnect" data-n="${esc(i.name)}">Disconnect</button>`:`<button class="btn primary" data-action="set-mp-connect" data-s="${slug(i.name)}">Connect</button>`}</div></div>
   ${UI.tabs([{key:'about',label:'About'},{key:'pricing',label:'Pricing'},{key:'regions',label:'Supported Regions'}],'about','mpd')}
   <div class="card pad" style="max-width:860px">
   ${UI.panel('mpd','about',`<h3>About ${esc(i.name)}</h3><p>${about}</p><ul style="padding-left:18px"><li>Set up in a few minutes from this page</li><li>Works with Dine-in QR, Pick-Up, Delivery and Tablet menus</li><li>Disconnect at any time from My Integrations</li></ul>`,'about')}
   ${UI.panel('mpd','pricing',`<h3>Pricing</h3><p>${i.price==='Free'?`There is no extra Proview fee for this integration. ${i.group==='payment'?`${esc(i.name)}'s own transaction fees apply.`:''}`:`This integration costs <strong>${esc(i.price)}</strong> per venue, billed with your Proview subscription.`}</p>`,'about')}
   ${UI.panel('mpd','regions',`<h3>Supported Regions</h3><div class="chips">${regions.map(r=>`<span class="chip">${r}</span>`).join('')}</div>`,'about')}</div>`},{nav:'marketplace'});
A('mp-site',el=>App.toast('Opening '+el.dataset.n+' website…'));
A('mp-connect',el=>{const i=findInt(el.dataset.s);const fields={payment:[['Publishable Key','pk_live_…'],['Secret Key','sk_live_…'],['Merchant ID','']],pos:[['API Key',''],['Location ID','']],printer:[['Printer IP Address','192.168.1.50'],['Port','9100']],access:[['Site Key','']]}[i.group];
  App.modal({title:'Connect '+esc(i.name),body:`<p class="muted" style="margin-top:0">Enter the details from your ${esc(i.name)} account to connect it to ${esc(S.venue.name)}.</p>`+fields.map(([l,ph],n)=>F(l,UI.input({id:'mpf'+n,placeholder:ph}),{required:n===0})).join(''),
   footer:`<button class="btn secondary" data-close>Cancel</button><button class="btn primary" data-action="set-mp-do-connect" data-n="${esc(i.name)}">Connect</button>`})});
A('mp-do-connect',el=>{if(!$('#mpf0').value.trim())return App.toast('Fill in the required field');S.connected.push({name:el.dataset.n,date:'08/11/2026 '+nowStr().slice(11),status:'Active'});App.closeModal();App.render();App.toast(el.dataset.n+' connected')});
A('mp-disconnect',el=>App.modal({title:'Disconnect '+esc(el.dataset.n)+'?',body:'<p style="margin:0">Orders and payments will stop syncing with this integration.</p>',footer:`<button class="btn secondary" data-close>Cancel</button><button class="btn danger" data-action="set-mp-do-disconnect" data-n="${esc(el.dataset.n)}">Disconnect</button>`}));
A('mp-do-disconnect',el=>{S.connected=S.connected.filter(c=>c.name!==el.dataset.n);App.closeModal();App.render();App.toast(el.dataset.n+' disconnected')});

App.route('marketplace-my',()=>UI.pageHead({title:'Marketplace',back:'marketplace',learn:true})+mpTabs('my')+
  `<div class="card">${UI.table({cols:['Integration','Date Connected','Status',{label:'Actions',align:'right'}],rows:S.connected.map(c=>[`<div style="display:flex;gap:10px;align-items:center"><span class="itile" style="width:32px;height:32px;font-weight:700;font-size:12px">${initials(c.name)}</span><a href="#marketplace-detail--${slug(c.name)}"><strong>${esc(c.name)}</strong></a></div>`,c.date,UI.pill(c.status,'ok'),`<button class="btn danger sm" data-action="set-mp-disconnect" data-n="${esc(c.name)}">Disconnect</button>`])})}</div>`,{nav:'marketplace'});

/* =========================================================
   SETTINGS HUB (§5.2)
   ========================================================= */
App.route('settings',()=>UI.pageHead({title:'Settings',sub:'Manage all your venue settings and configurations'})+UI.hubCards([
  {icon:'pin',title:'Venue Information',text:'Manage your venue location and information',href:'settings-venue--location'},
  {icon:'table',title:'Operations',text:'Configure tables, staff, and service options',href:'settings-operations--tables'},
  {icon:'qr',title:'QR Codes',text:'Generate and manage QR codes for your venue',href:'settings-qr--view'},
  {icon:'palette',title:'Design & Display',text:'Customize menu design and display settings',href:'settings-design--qr'},
  {icon:'smile',title:'Welcome Page',text:'Configure welcome page settings',href:'settings-welcome--dinein'},
  {icon:'clock',title:'Operating Hours',text:'Set operating hours for your venue',href:'settings-hours--dinein'},
  {icon:'pound',title:'Price Options',text:'Configure pricing and currency options',href:'settings-price--dinein'},
  {icon:'translate',title:'Translation Center',text:'Translate your menu and content into multiple languages',href:'translation-center--menus'}]),{nav:'settings'});

const frame=(title,tabs,body,o={})=>UI.pageHead({title,back:'settings',learn:true,tutorial:o.tutorial,actions:o.actions||''})+tabs+body;
const rTabs=(base,items,a)=>UI.tabs(items.map(([k,l,x])=>({key:k,label:l,href:base+'--'+k,...(x||{})})),a);

/* ---------- Venue Information ---------- */
const VT=[['location','Location Settings'],['language','Language Options'],['social','Social Accounts'],['google','Google Business Profile']];
App.route('settings-venue',p=>{p=p||'location';const V=S.venue;let body='';
  if(p==='location')body=`<div class="form-card">${g2(F('Venue Name',inp('venue.name',V.name,'Venue name')),F('Venue ID',UI.input({value:V.id,attrs:'readonly style="background:var(--page)"'}),{help:'Used to log in to the tablet app and in your menu links.'}))}
    ${F('Logo',`<div style="display:flex;gap:12px;align-items:center">${UI.upload({label:'Upload',sm:true,accept:'.jpg,.jpeg,.png,.webp,.svg'})}<button class="btn secondary sm" data-action="set-logo-preview">${ic('eye','sm')}Preview</button></div>`,{help:'Square PNG or SVG works best, at least 512 × 512px.'})}
    ${F('Address',ta('venue.address',V.address,'Street address',2)+`<button class="btn ghost sm" style="margin-top:6px" data-action="set-map">${ic('pin','sm')}Select from the map</button>`)}
    ${g2(F('City',inp('venue.city',V.city)),F('Country',sel('venue.country',COUNTRIES,V.country)),F('State',inp('venue.state',V.state||'','County / state')),F('Zip Code',inp('venue.zip',V.zip)),F('Phone Number',inp('venue.phone',V.phone,'',{type:'tel'})),F('Timezone',sel('venue.timezone',TZ,V.timezone),{help:'Current date is '+nowStr()}))}
    ${F('Website',inp('venue.website',V.website,'https://www.yourvenue.co.uk'))}${saveBtn()}</div>`;
  if(p==='language'){const langs=v('languages',[]);body=`<div class="form-card"><div class="card pad" style="background:var(--brand-tint-subtle);display:flex;gap:10px;margin-bottom:16px">${ic('info')}<span>To translate your menu into the languages you choose, go to <a href="#translation-center--menus">Translation Center</a>.</span></div>
    ${F('Default Language',sel('defaultLang',LANGS,'English'))}
    ${F('Additional Languages',`<div class="chips" id="langChips">${langs.map(l=>`<span class="chip">${esc(l)}<button class="iconbtn" style="width:20px;height:20px;border:0;background:none" data-action="set-lang-remove" data-l="${esc(l)}" aria-label="Remove ${esc(l)}">${ic('x','sm')}</button></span>`).join('')||'<span class="muted">No additional languages yet.</span>'}</div><button class="btn secondary sm" style="margin-top:10px" data-action="set-lang-add">${ic('plus','sm')}Add Language</button>`)}${saveBtn()}</div>`}
  if(p==='social'){const SO=[['Website','https://'],['Instagram','instagram.com/'],['Facebook','facebook.com/'],['X','x.com/'],['Foursquare','foursquare.com/'],['Trip Advisor','tripadvisor.co.uk/'],['Snapchat','snapchat.com/add/'],['Zomato','zomato.com/'],['Tiktok','tiktok.com/@'],['Spotify','open.spotify.com/'],['WhatsApp','https://wa.me/',1],['Yelp','yelp.co.uk/',1],['Linktree','linktr.ee/',1]];
    body=`<div class="form-card"><p class="muted" style="margin-top:0">These links appear as icons on your welcome page so guests can follow you.</p>${g2(...SO.map(([l,pre,n])=>F(l+(n?newTag:''),inp('social.'+l,'','',{prefix:pre}))))}${saveBtn()}</div>`}
  if(p==='google'){const c=v('google',false);body=`<div class="form-card" style="display:grid;grid-template-columns:1fr 280px;gap:24px;align-items:center;max-width:960px">
    <div>${h3('Connect Your Restaurant to Google','Link your Google Business Profile so your Proview menu, opening hours and reviews stay in step with what people see on Google.')}
    <ul style="padding-left:18px;line-height:26px"><li>Get more visibility on Google Search & Maps</li><li>Keep your menu up to date on Google automatically</li><li>Manage reviews from your Proview dashboard</li></ul>
    ${c?`<div style="display:flex;gap:10px;align-items:center">${UI.pill(ic('check','sm')+'Connected as '+esc(v('googleListing',S.venue.name)),'ok')}<button class="btn danger sm" data-action="set-google-off">Disconnect</button></div>`:`<button class="btn primary" data-action="set-google">${ic('globe','sm')}Connect with Google</button>`}</div>
    <div class="card" style="padding:14px;background:var(--page)"><div style="height:8px;width:60%;background:var(--border);border-radius:4px;margin-bottom:10px"></div><div class="card pad" style="padding:12px"><strong style="color:var(--ink)">${esc(S.venue.name)}</strong><div class="stars" style="font-size:13px">★★★★★ <span class="muted">4.7</span></div><small class="muted">Restaurant · ${esc(S.venue.city)}</small><div style="display:flex;gap:6px;margin-top:8px"><span class="chip">Menu</span><span class="chip">Order</span><span class="chip">Reserve</span></div></div></div></div>`}
  return frame('Venue Information',rTabs('settings-venue',VT,p),body)},{nav:'settings'});
A('logo-preview',()=>{const f=$('#view .upload input')?.files?.[0];const url=f?URL.createObjectURL(f):'';App.modal({title:'Logo Preview',body:`<div style="display:grid;place-items:center;padding:20px;background:var(--page);border-radius:12px">${url?`<img src="${url}" alt="Logo preview" style="max-width:220px;max-height:220px">`:`<span class="avatar" style="width:120px;height:120px;font-size:40px">${initials(S.venue.name)}</span>`}</div><p class="muted" style="text-align:center">${url?'This is how your logo will appear on the welcome page.':'No logo uploaded yet – your initials are shown instead.'}</p>`})});
A('map',()=>App.modal({title:'Select from the map',wide:true,body:`${UI.searchBox('Search for an address','id="mapQ" style="width:100%"').replace('class="search"','class="search" style="max-width:none;margin-bottom:12px"')}
  <div class="canvas" style="min-height:320px;background-color:#EAF2E3;display:grid;place-items:center"><div style="text-align:center;color:var(--bad)">${ic('pin').replace('class="i "','class="i " style="width:40px;height:40px"')}<div class="pill" style="margin-top:6px">${esc(S.venue.address)}</div></div></div><p class="muted">Drag the map to move the pin, or search for an address above.</p>`,
  footer:`<button class="btn secondary" data-close>Cancel</button><button class="btn primary" data-action="set-map-use">Use this location</button>`}));
A('map-use',()=>{const q=$('#mapQ')?.value.trim();if(q){const t=$('#view [data-k="venue.address"]');if(t)t.value=q}App.closeModal();App.toast('Location selected')});
A('lang-add',()=>{const have=v('languages',[]);App.modal({title:'Choose languages',body:F('Languages',`<div style="display:grid;grid-template-columns:1fr 1fr;gap:8px;max-height:300px;overflow:auto">${LANGS.filter(l=>l!==v('defaultLang','English')).map(l=>UI.check(l,have.includes(l),`data-lang="${l}"`)).join('')}</div>`),footer:`<button class="btn secondary" data-close>Cancel</button><button class="btn primary" data-action="set-lang-save">Save</button>`})});
A('lang-save',()=>{S.cfg.languages=$$('#modal [data-lang]').filter(c=>c.checked).map(c=>c.dataset.lang);App.closeModal();App.render();App.toast('Languages updated')});
A('lang-remove',el=>{S.cfg.languages=v('languages',[]).filter(l=>l!==el.dataset.l);App.render()});
A('google',()=>App.modal({title:'Connect with Google',body:`<p class="muted" style="margin-top:0">Choose the Google account and Business Profile for this venue.</p>${F('Google account',UI.select(['altun@proviewtech.co.uk','Use another account…']))}${F('Business Profile',UI.select([S.venue.name+' – '+S.venue.address,'Create a new profile…'],'','id="gListing"'))}`,footer:`<button class="btn secondary" data-close>Cancel</button><button class="btn primary" data-action="set-google-do">Connect</button>`}));
A('google-do',()=>{S.cfg.google=true;S.cfg.googleListing=S.venue.name;App.closeModal();App.render();App.toast('Google Business Profile connected')});
A('google-off',()=>{S.cfg.google=false;App.render();App.toast('Disconnected from Google')});

/* ---------- Operations ---------- */
const OT=[['tables','Tables'],['staff','Staff'],['charges','Extra Charges'],['service','Service Options'],['devices','Device Management',{tag:'Tablet'}]];
let opView='list',tQ='',zoom=1,fpGrid=true,fpSel=null;const collapsed=new Set();let areaOn=null;
App.route('settings-operations',p=>{p=p||'tables';let body='',act='';
  if(p==='tables')body=tablesView();
  if(p==='staff'){act=`<button class="btn primary" data-action="set-staff-drawer">${ic('plus','sm')}Add New Staff Member</button>`;
    body=`<div class="card">${UI.table({cols:['Name','Check Name','Pincode',{label:'Actions',align:'right'}],rows:S.staff.map(s=>[`<strong style="color:var(--ink)">${esc(s.first+' '+s.last)}</strong>${s.status!=='Active'?' '+UI.pill(s.status,'grey'):''}`,esc(s.check),'••••',`<button class="btn ghost sm" data-action="set-staff-drawer" data-id="${s.id}">${ic('edit','sm')}Edit</button><button class="btn ghost sm" style="color:var(--bad)" data-action="set-staff-del" data-id="${s.id}">${ic('trash','sm')}</button>`])})}</div>`}
  if(p==='charges'){const C=v('charges',{discounts:[],service:[],taxes:[]});const blk=(k,t,btn,sub)=>`<div class="card pad" style="margin-bottom:16px">${h3(t,sub)}<div style="display:grid;grid-template-columns:1fr 160px 40px;gap:10px;font-weight:600;color:var(--ink);font-size:13px;margin-bottom:6px"><span>Name</span><span>Rate</span><span></span></div><div id="ch-${k}">${(C[k]||[]).map(r=>chRow(k,r)).join('')}</div><button class="btn secondary sm" data-action="set-ch-add" data-k="${k}">${ic('plus','sm')}${btn}</button></div>`;
    body=`<div style="max-width:860px">${blk('discounts','Discounts','Add Discount','Discounts staff can apply to a bill.')}${blk('service','Service Charges','Add Service Charge','Added to dine-in bills, e.g. 12.5% service.')}${blk('taxes','Taxes','Add Tax','Shown on receipts and reports.')}${saveBtn('set-ch-save')}</div>`}
  if(p==='service'){const L=v('serviceOpts',[]);body=`<div class="form-card">${h3('Service Options','Add the requests guests can send from their table, such as "Ask for the bill" or "Call a waiter". With no options added, guests simply send a general request.')}<div id="svcList">${L.map(svRow).join('')}</div><button class="btn secondary sm" data-action="set-sv-add">${ic('plus','sm')}Add</button>${saveBtn('set-sv-save')}</div>`}
  if(p==='devices')body=`<div class="card pad" style="background:var(--brand-tint-subtle);display:flex;gap:10px;margin-bottom:16px">${ic('tablet')}<span>Tablets signed in to the Proview tablet app with your Venue ID and pincode appear here. Remove a device to sign it out.</span></div><div class="card">${UI.table({cols:['Name','OS','OS Version','Device Id','App Version','Model','Last Connected','Actions'],rows:[]})}</div>`;
  return frame('Operations',rTabs('settings-operations',OT,p),body,{tutorial:true,actions:act})},{nav:'settings'});
App.after('settings-operations',p=>{if((p||'tables')==='tables'&&opView==='floor')fpRender()});

function tablesView(){const has=S.tables.length;
  const tb=`<div class="toolbar">${`<div class="seg"><button class="${opView==='list'?'on':''}" data-action="set-opview" data-v="list">${ic('list','sm')}List</button><button class="${opView==='floor'?'on':''}" data-action="set-opview" data-v="floor">${ic('map','sm')}Floor plan</button></div>`}
    ${opView==='list'?UI.searchBox('Search',`data-input="set-tsearch" value="${esc(tQ)}"`):''}<span class="grow"></span>
    <button class="btn secondary" data-action="set-qr-all" ${has?'':'disabled'}>${ic('download','sm')}Download QR Codes</button><button class="btn primary" data-action="set-table-drawer">${ic('plus','sm')}Add New Tables</button></div>`;
  if(opView==='floor')return tb+floorView();
  if(!areaOn)areaOn=new Set(S.areas);S.areas.forEach(a=>{if(!areaOn._seen?.has(a)){areaOn.add(a)}});areaOn._seen=new Set(S.areas);
  return tb+`<div class="card pad" style="display:flex;gap:16px;align-items:center;flex-wrap:wrap;margin-bottom:16px;padding:12px 16px">${UI.check('<strong>All</strong>',S.areas.every(a=>areaOn.has(a)),'data-change="set-area-all"')}${S.areas.map(a=>UI.check(esc(a),areaOn.has(a),`data-change="set-area-f" data-a="${esc(a)}"`)).join('')}<span class="grow" style="flex:1"></span><button class="btn ghost sm" data-action="set-area-add">${ic('plus','sm')}Add Area</button></div><div id="areaCards">${areaCards()}</div>`}
function areaCards(){const q=tQ.toLowerCase();return S.areas.filter(a=>areaOn.has(a)).map(a=>{const ts=S.tables.filter(t=>t.area===a&&t.name.toLowerCase().includes(q));const c=collapsed.has(a);
  return `<div class="card" style="margin-bottom:14px"><div class="card-head">${UI.check('',false,'aria-label="Select area"')}<h3>${esc(a)}</h3><span class="pill grey">${ts.length} tables</span><div class="right" style="display:flex;gap:6px"><button class="btn ghost sm" data-action="set-table-drawer" data-area="${esc(a)}">${ic('plus','sm')}Add Table</button><button class="iconbtn" style="width:32px;height:32px" data-action="set-area-toggle" data-a="${esc(a)}" aria-label="Collapse">${ic(c?'chevd':'chevu','sm')}</button></div></div>
  ${c?'':ts.length?UI.table({cols:['Table','Seats','Online Reservation','QR Code',{label:'Actions',align:'right'}],rows:ts.map(t=>[`<strong style="color:var(--ink)">${esc(t.name)}</strong>`,`${t.min}–${t.max}`,t.res?UI.pill('Available','ok'):UI.pill('Off','grey'),`<button class="btn ghost sm" data-action="set-table-qr" data-id="${t.id}">${ic('qr','sm')}View</button>`,`<button class="btn ghost sm" data-action="set-table-edit" data-id="${t.id}">${ic('edit','sm')}Edit</button><button class="btn ghost sm" style="color:var(--bad)" data-action="set-table-del" data-id="${t.id}" aria-label="Delete">${ic('trash','sm')}</button>`])}):UI.empty('table','No tables in this area',q?'No tables match your search.':'Add tables to start taking orders with table numbers.')}</div>`}).join('')||`<div class="card">${UI.empty('table','No areas selected')}</div>`}
A('opview',el=>{opView=el.dataset.v;App.render()});
A('tsearch',el=>{tQ=el.value;$('#areaCards').innerHTML=areaCards()});
A('area-all',el=>{areaOn=new Set(el.checked?S.areas:[]);areaOn._seen=new Set(S.areas);App.render()});
A('area-f',el=>{el.checked?areaOn.add(el.dataset.a):areaOn.delete(el.dataset.a);App.render()});
A('area-toggle',el=>{const a=el.dataset.a;collapsed.has(a)?collapsed.delete(a):collapsed.add(a);$('#areaCards').innerHTML=areaCards()});
A('area-add',()=>App.modal({title:'Add Area',body:F('Area Name',UI.input({id:'areaName',placeholder:'e.g. Terrace'}),{required:true}),footer:`<button class="btn secondary" data-close>Cancel</button><button class="btn primary" data-action="set-area-save">Save</button>`}));
A('area-save',()=>{const n=$('#areaName').value.trim();if(!n)return App.toast('Enter an area name');if(!S.areas.includes(n))S.areas.push(n);areaOn&&areaOn.add(n);App.closeModal();App.render();App.toast('Area added')});
A('table-drawer',el=>{const area=el.dataset.area||'No Area';App.drawer({title:'Add New Table',body:`
  <div class="radio-cards" style="grid-template-columns:1fr 1fr;margin-bottom:16px"><label class="radio-card"><input type="radio" name="tmode" value="auto" checked data-change="set-tmode"><div><strong>Automatic Table Names</strong><small>Numbered in order, e.g. Table 1, Table 2</small></div></label><label class="radio-card"><input type="radio" name="tmode" value="custom" data-change="set-tmode"><div><strong>Custom Table Names</strong><small>Type your own names</small></div></label></div>
  <div id="tAuto">${F('Label',UI.input({id:'tLabel',value:'Table',placeholder:'Table Title'}))}</div>
  <div id="tCustom" hidden>${F('Table Names',UI.textarea({id:'tNames',placeholder:'Window 1\nBar 2\nGarden',rows:4}),{help:'One table name per line.'})}</div>
  ${F('Selected Area',UI.select(S.areas,area,'id="tArea"'),{help:'Optional'})}
  <div id="tNums">${g2(F('Number of Tables',UI.input({id:'tCount',type:'number',value:'1',attrs:'min="1" max="200"'})),F('Starting from',UI.input({id:'tStart',type:'number',value:String(S.tables.length+1),attrs:'min="1"'})))}</div>
  ${g2(F('Min Seats',UI.input({id:'tMin',type:'number',value:'1',attrs:'min="1"'})),F('Max Seats',UI.input({id:'tMax',type:'number',value:'4',attrs:'min="1"'})))}
  ${UI.toggleRow(`Available in online reservation <span title="Guests can book this table online">${ic('info','sm')}</span>`,'',true,'id="tRes"')}`,
  footer:`<button class="btn secondary" data-close>Cancel</button><button class="btn primary" data-action="set-table-create">Create</button>`})});
A('tmode',el=>{const c=el.value==='custom';$('#tAuto').hidden=c;$('#tNums').hidden=c;$('#tCustom').hidden=!c});
A('table-create',()=>{const custom=$('[name=tmode]:checked').value==='custom';const area=$('#tArea').value,min=+$('#tMin').value||1,max=Math.max(min,+$('#tMax').value||min),res=$('#tRes').checked;let names=[];
  if(custom)names=$('#tNames').value.split('\n').map(s=>s.trim()).filter(Boolean);else{const n=Math.min(200,+$('#tCount').value||1),st=+$('#tStart').value||1,l=$('#tLabel').value.trim()||'Table';for(let i=0;i<n;i++)names.push(`${l} ${st+i}`)}
  if(!names.length)return App.toast('Add at least one table name');names.forEach(n=>S.tables.push({id:uid(),name:n,area,min,max,res}));App.closeDrawer();App.render();App.toast(`${names.length} table${names.length>1?'s':''} created`)});
A('table-edit',el=>{const t=S.tables.find(x=>x.id===el.dataset.id);App.drawer({title:'Edit '+esc(t.name),body:F('Table Name',UI.input({id:'teName',value:t.name}),{required:true})+F('Area',UI.select(S.areas,t.area,'id="teArea"'))+g2(F('Min Seats',UI.input({id:'teMin',type:'number',value:t.min})),F('Max Seats',UI.input({id:'teMax',type:'number',value:t.max})))+UI.toggleRow('Available in online reservation','',t.res,'id="teRes"'),
  footer:`<button class="btn secondary" data-close>Cancel</button><button class="btn primary" data-action="set-table-update" data-id="${t.id}">Save</button>`})});
A('table-update',el=>{const t=S.tables.find(x=>x.id===el.dataset.id);Object.assign(t,{name:$('#teName').value.trim()||t.name,area:$('#teArea').value,min:+$('#teMin').value||1,max:+$('#teMax').value||1,res:$('#teRes').checked});App.closeDrawer();App.render();App.toast('Table saved')});
A('table-del',el=>{const t=S.tables.find(x=>x.id===el.dataset.id);App.modal({title:'Delete '+esc(t.name)+'?',body:'<p style="margin:0">Its QR code will stop working. This can\'t be undone.</p>',footer:`<button class="btn secondary" data-close>Cancel</button><button class="btn danger" data-action="set-table-del-do" data-id="${t.id}">Delete</button>`})});
A('table-del-do',el=>{S.tables=S.tables.filter(t=>t.id!==el.dataset.id);S.floor=S.floor.filter(f=>f.tableId!==el.dataset.id);App.closeModal();App.render();App.toast('Table deleted')});
A('table-qr',el=>{const t=S.tables.find(x=>x.id===el.dataset.id);App.modal({title:esc(t.name)+' QR Code',body:`${qrc(t.id,200)}<p class="muted" style="text-align:center">${GU({t:t.name})}</p>`,footer:`<button class="btn secondary" data-copy="${GU({t:t.name})}">${ic('copy','sm')}Copy Link</button><button class="btn primary" data-action="download">${ic('download','sm')}Download</button>`})});
function qrAllModal(){if(!S.tables.length){App.toast('Add tables first');return}App.modal({title:'Table QR Codes',wide:true,body:`<div class="grid g4" style="gap:12px;max-height:60vh;overflow:auto">${S.tables.map(t=>`<div class="card pad" style="text-align:center;padding:12px">${qrc(t.id,120)}<strong style="color:var(--ink);display:block;margin-top:6px">${esc(t.name)}</strong><small class="muted">${esc(t.area)}</small></div>`).join('')}</div>`,footer:`<button class="btn secondary" data-close>Close</button><button class="btn primary" data-action="download">${ic('download','sm')}Download all (${S.tables.length})</button>`})}
A('qr-all',qrAllModal);

/* staff */
A('staff-drawer',el=>{const s=S.staff.find(x=>x.id===el.dataset.id)||{id:String(S.staff.length+1).padStart(3,'0'),first:'',last:'',pin:'',check:'',status:'Active',_new:1};
  App.drawer({title:s._new?'Add Staff Member':'Edit Staff Member',body:F('ID',UI.input({id:'sfId',value:s.id}))+g2(F('First Name',UI.input({id:'sfFirst',value:s.first}),{required:true}),F('Last Name',UI.input({id:'sfLast',value:s.last})))+
   F('Pincode',`<div style="display:flex;gap:8px">${UI.input({id:'sfPin',value:s.pin,placeholder:'4 digits',attrs:'maxlength="4" inputmode="numeric"'})}<button class="btn secondary" data-action="set-pin-gen" data-t="sfPin">Generate</button></div>`,{help:'Staff use this to sign in on the tablet app.',required:true})+
   F('Check Name',UI.input({id:'sfCheck',value:s.check,placeholder:'Name printed on the bill'}))+F('Status',UI.select(['Active','Passive'],s.status,'id="sfStatus"')),
   footer:`<button class="btn secondary" data-close>Cancel</button><button class="btn primary" data-action="set-staff-save" data-id="${s._new?'':s.id}">Save</button>`})});
A('pin-gen',el=>{$('#'+el.dataset.t).value=String(Math.floor(1000+Math.random()*9000))});
A('staff-save',el=>{const d={id:$('#sfId').value.trim(),first:$('#sfFirst').value.trim(),last:$('#sfLast').value.trim(),pin:$('#sfPin').value.trim(),check:$('#sfCheck').value.trim(),status:$('#sfStatus').value};
  if(!d.first||!/^\d{4}$/.test(d.pin))return App.toast('Enter a first name and a 4-digit pincode');if(!d.check)d.check=d.first;
  const ex=S.staff.find(x=>x.id===el.dataset.id);ex?Object.assign(ex,d):S.staff.push(d);App.closeDrawer();App.render();App.toast('Staff member saved')});
A('staff-del',el=>{S.staff=S.staff.filter(s=>s.id!==el.dataset.id);App.render();App.toast('Staff member removed')});

/* charges + service options */
const chRow=(k,r={name:'',rate:''})=>`<div class="ch-row" style="display:grid;grid-template-columns:1fr 160px 40px;gap:10px;margin-bottom:8px"><input class="input" data-n value="${esc(r.name)}" placeholder="Name" aria-label="Name">${UI.input({value:r.rate,placeholder:'0',suffix:'%',attrs:'data-r aria-label="Rate"'})}<button class="iconbtn" data-action="set-row-del" aria-label="Remove">${ic('trash','sm')}</button></div>`;
A('ch-add',el=>$('#ch-'+el.dataset.k).insertAdjacentHTML('beforeend',chRow(el.dataset.k)));
A('row-del',el=>el.closest('.ch-row,.sv-row').remove());
A('ch-save',()=>{const C={};['discounts','service','taxes'].forEach(k=>C[k]=$$('#ch-'+k+' .ch-row').map(r=>({name:r.querySelector('[data-n]').value,rate:r.querySelector('[data-r]').value})).filter(r=>r.name));S.cfg.charges=C;App.render();App.toast('Settings saved')});
const svRow=t=>`<div class="sv-row" style="display:flex;gap:10px;margin-bottom:8px"><input class="input" value="${esc(t)}" placeholder="e.g. Request checkout" aria-label="Service option"><button class="iconbtn" data-action="set-row-del" aria-label="Remove">${ic('trash','sm')}</button></div>`;
A('sv-add',()=>$('#svcList').insertAdjacentHTML('beforeend',svRow('')));
A('sv-save',()=>{S.cfg.serviceOpts=$$('#svcList input').map(i=>i.value.trim()).filter(Boolean);App.render();App.toast('Settings saved')});

/* ---------- floor plan ---------- */
const SH={Round:{w:72,h:72,r:'50%',t:1},Square:{w:72,h:72,r:'10px',t:1},Rectangle:{w:128,h:72,r:'10px',t:1},Booth:{w:128,h:64,r:'24px 24px 8px 8px',t:1},'Bar / Counter':{w:200,h:44,r:'8px',t:1},Door:{w:56,h:12,r:'3px'},Wall:{w:180,h:10,r:'2px'},Plant:{w:36,h:36,r:'50%'},Window:{w:96,h:10,r:'2px'}};
function floorView(){const un=S.tables.filter(t=>!S.floor.some(f=>f.tableId===t.id));
  return `<div style="display:grid;grid-template-columns:220px minmax(0,1fr) 260px;gap:16px;align-items:start">
  <div class="card pad" style="padding:14px"><div class="eyebrow">Add elements</div><p class="help" style="margin:4px 0 10px">Drag or click to add</p>
   <div style="display:grid;grid-template-columns:1fr 1fr;gap:8px">${Object.entries(SH).filter(([,s])=>s.t).map(([k,s])=>palBtn(k,s)).join('')}</div>
   <div class="eyebrow" style="margin-top:16px">Objects</div><div style="display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-top:8px">${Object.entries(SH).filter(([,s])=>!s.t).map(([k,s])=>palBtn(k,s)).join('')}</div>
   ${un.length?`<div class="eyebrow" style="margin-top:16px">Unplaced tables</div><div style="display:flex;flex-direction:column;gap:6px;margin-top:8px">${un.slice(0,12).map(t=>`<button class="chip-btn" data-action="set-fp-place" data-id="${t.id}">${ic('plus','sm')}${esc(t.name)}</button>`).join('')}</div>`:''}
   <button class="btn ghost sm" style="margin-top:14px;width:100%" data-action="set-area-add">${ic('plus','sm')}Add area</button></div>
  <div><div class="toolbar" style="margin-bottom:8px">${UI.check('Grid',fpGrid,'data-change="set-fp-grid"')}<span class="grow"></span><button class="iconbtn" style="width:32px;height:32px" data-action="set-fp-zoom" data-d="-1" aria-label="Zoom out">${ic('minus','sm')}</button><span id="fpZoom" style="min-width:48px;text-align:center;font-weight:600">${Math.round(zoom*100)}%</span><button class="iconbtn" style="width:32px;height:32px" data-action="set-fp-zoom" data-d="1" aria-label="Zoom in">${ic('plus','sm')}</button><button class="btn secondary sm" data-action="set-fp-fit">${ic('full','sm')}Fit</button></div>
   <div class="canvas" id="fpCanvas" style="overflow:hidden;height:520px;${fpGrid?'':'background-image:none'}"><div id="fpInner" style="position:absolute;inset:0;transform-origin:0 0;transform:scale(${zoom})"></div>${S.floor.length?'':'<div id="fpEmpty" style="position:absolute;inset:0;display:grid;place-items:center;color:var(--muted);pointer-events:none">Drag tables from the left to start your floor plan</div>'}</div></div>
  <div class="card pad" style="padding:14px" id="fpDetails"></div></div>`}
const palBtn=(k,s)=>`<button class="select-card" style="padding:10px;text-align:center" draggable="true" data-shape="${k}" data-action="set-fp-add"><span style="display:block;margin:0 auto 6px;width:${Math.min(44,s.w/2.6)}px;height:${Math.max(6,Math.min(30,s.h/2.6))}px;border-radius:${s.r};border:2px solid var(--brand-700);background:${k==='Plant'?'#CDE8C4':'var(--brand-tint)'}"></span><small style="font-weight:600;color:var(--ink)">${k}</small></button>`;
function fpRender(){const inner=$('#fpInner');if(!inner)return;inner.innerHTML=S.floor.map(f=>{const s=SH[f.kind];const t=f.tableId&&S.tables.find(x=>x.id===f.tableId);
  return `<div class="fp-el" data-id="${f.id}" style="position:absolute;left:${f.x}px;top:${f.y}px;width:${s.w}px;height:${s.h}px;border-radius:${s.r};background:${f.kind==='Plant'?'#CDE8C4':f.kind==='Window'?'#CFE6FA':s.t?'var(--brand-tint)':'#C5CDD6'};border:2px solid ${fpSel===f.id?'var(--brand-900)':s.t?'var(--brand-700)':'#8793A0'};${fpSel===f.id?'box-shadow:0 0 0 4px rgba(21,101,192,.2);':''}display:grid;place-items:center;cursor:move;user-select:none;touch-action:none;font-size:12px;font-weight:700;color:var(--brand-900);text-align:center;line-height:14px">${t?esc(t.name)+`<br><small style="font-weight:500">${t.max} seats</small>`:''}</div>`}).join('');
  const e=$('#fpEmpty');if(e)e.style.display=S.floor.length?'none':'grid';fpDetails()}
function fpDetails(){const d=$('#fpDetails');if(!d)return;const f=S.floor.find(x=>x.id===fpSel);
  if(!f){d.innerHTML=`<div class="eyebrow">Table details</div><p class="muted">Select a table on the plan to edit its details.</p>`;return}
  const t=f.tableId&&S.tables.find(x=>x.id===f.tableId);
  d.innerHTML=`<div class="eyebrow">${t?'Table details':'Object'}</div><p style="margin:6px 0 12px;font-weight:600;color:var(--ink)">${f.kind}</p>`+(t?F('Name',`<input class="input" value="${esc(t.name)}" data-input="set-fp-edit" data-f="name">`)+F('Seats',`<input class="input" type="number" min="1" value="${t.max}" data-input="set-fp-edit" data-f="max">`)+F('Area',UI.select(S.areas,t.area,'data-change="set-fp-edit" data-f="area"')):'')+`<button class="btn danger sm" data-action="set-fp-del">${ic('trash','sm')}Delete</button>`}
function fpAdd(kind,x,y,tableId){const s=SH[kind];let tid=tableId;
  if(s.t&&!tid){const n=S.tables.length+1;const t={id:uid(),name:'Table '+n,area:S.areas[0],min:1,max:kind==='Bar / Counter'?6:kind==='Round'||kind==='Square'?4:6,res:true};S.tables.push(t);tid=t.id}
  const f={id:uid(),kind,x:Math.max(0,Math.round(x)),y:Math.max(0,Math.round(y)),tableId:tid||null};S.floor.push(f);fpSel=f.id;fpRender()}
A('fp-add',el=>{const n=S.floor.length;fpAdd(el.dataset.shape,40+(n%5)*140,40+Math.floor(n/5)*120%440)});
A('fp-place',el=>{const t=S.tables.find(x=>x.id===el.dataset.id);const n=S.floor.length;fpAdd('Square',40+(n%5)*140,40+Math.floor(n/5)*120%440,t.id);App.render()});
A('fp-grid',el=>{fpGrid=el.checked;$('#fpCanvas').style.backgroundImage=fpGrid?'':'none'});
A('fp-zoom',el=>{zoom=Math.min(2,Math.max(.4,+(zoom+(+el.dataset.d)*.1).toFixed(2)));$('#fpInner').style.transform=`scale(${zoom})`;$('#fpZoom').textContent=Math.round(zoom*100)+'%'});
A('fp-fit',()=>{if(!S.floor.length){zoom=1}else{const c=$('#fpCanvas');const mx=Math.max(...S.floor.map(f=>f.x+SH[f.kind].w))+40,my=Math.max(...S.floor.map(f=>f.y+SH[f.kind].h))+40;zoom=Math.max(.4,Math.min(1.5,+Math.min(c.clientWidth/mx,c.clientHeight/my).toFixed(2)))}$('#fpInner').style.transform=`scale(${zoom})`;$('#fpZoom').textContent=Math.round(zoom*100)+'%'});
A('fp-edit',el=>{const f=S.floor.find(x=>x.id===fpSel);const t=S.tables.find(x=>x.id===f.tableId);if(!t)return;const k=el.dataset.f;t[k]=k==='max'?Math.max(1,+el.value||1):el.value;const box=$(`.fp-el[data-id="${f.id}"]`);if(box)box.innerHTML=`${esc(t.name)}<br><small style="font-weight:500">${t.max} seats</small>`});
A('fp-del',()=>{S.floor=S.floor.filter(f=>f.id!==fpSel);fpSel=null;fpRender();App.toast('Removed from floor plan')});
let drag=null;
document.addEventListener('pointerdown',e=>{const el=e.target.closest('.fp-el');if(!el)return;const f=S.floor.find(x=>x.id===el.dataset.id);if(!f)return;
  if(fpSel!==f.id){fpSel=f.id;$$('.fp-el').forEach(x=>{const on=x===el;x.style.borderColor=on?'var(--brand-900)':'';x.style.boxShadow=on?'0 0 0 4px rgba(21,101,192,.2)':''});fpDetails()}
  drag={f,el,sx:e.clientX,sy:e.clientY,ox:f.x,oy:f.y};e.preventDefault()});
document.addEventListener('pointermove',e=>{if(!drag)return;drag.f.x=Math.max(0,Math.round(drag.ox+(e.clientX-drag.sx)/zoom));drag.f.y=Math.max(0,Math.round(drag.oy+(e.clientY-drag.sy)/zoom));drag.el.style.left=drag.f.x+'px';drag.el.style.top=drag.f.y+'px'});
document.addEventListener('pointerup',()=>{drag=null});
document.addEventListener('dragstart',e=>{const b=e.target.closest&&e.target.closest('[data-shape]');if(b){e.dataTransfer.setData('text/plain',b.dataset.shape);e.dataTransfer.effectAllowed='copy'}});
document.addEventListener('dragover',e=>{if(e.target.closest&&e.target.closest('#fpCanvas'))e.preventDefault()});
document.addEventListener('drop',e=>{const c=e.target.closest&&e.target.closest('#fpCanvas');if(!c)return;e.preventDefault();const k=e.dataTransfer.getData('text/plain');if(!SH[k])return;const r=c.getBoundingClientRect();fpAdd(k,(e.clientX-r.left)/zoom-SH[k].w/2,(e.clientY-r.top)/zoom-SH[k].h/2)});

/* ---------- QR Codes ---------- */
function qrc(seed,size=180,fg='#1A2330',bg='#FFFFFF'){return UI.qr(seed,size).replaceAll('#1A2330','\u0000').replace('fill="#fff"/>',`fill="${bg}"/>`).replaceAll('fill="#fff"',`fill="${bg}"`).replaceAll('\u0000',fg)}
const QT=[['view','View Only'],['ordering','View & Ordering'],['tablet','Tablet']];
App.route('settings-qr',p=>{p=p||'view';let body='';
  if(p==='view')body=`<div style="display:grid;grid-template-columns:minmax(0,1fr) 340px;gap:20px;align-items:start;max-width:1100px"><div class="form-card">${h3('QR Code Colors','Match the code to your table stands and print.')}
     ${g2(F('QR Color',color('qr.fg','#1A2330','data-input="set-qr-color"')),F('Background Color',color('qr.bg','#FFFFFF','data-input="set-qr-color"')))}
     <div class="card pad" style="background:var(--brand-tint-subtle);display:flex;gap:12px;align-items:flex-start;margin-top:8px"><span style="font-size:20px">💡</span><div style="flex:1"><strong style="color:var(--ink)">Cool Tip</strong><div class="help" style="margin-top:2px">Share this link on your social media so people can browse your menu before they visit.</div><div style="display:flex;gap:8px;margin-top:10px">${UI.input({value:GU({v:1}),attrs:'readonly'})}<button class="btn secondary" data-copy="${GU({v:1})}">${ic('copy','sm')}Copy Link</button></div></div></div>${saveBtn()}</div>
     <div class="card pad" style="text-align:center"><h3>QR Code for Menu Display</h3><p class="muted" style="margin:4px 0 14px">Use this code to show your view-only dine-in menu.</p><div id="qrPrev" style="padding:14px;border-radius:12px;background:${v('qr.bg','#FFFFFF')};display:inline-block;border:1px solid var(--border)">${qrc('menu-display',200,v('qr.fg','#1A2330'),v('qr.bg','#FFFFFF'))}</div>
     <div style="display:flex;gap:8px;justify-content:center;margin-top:14px"><button class="btn primary" data-action="download">${ic('download','sm')}Download</button><button class="btn secondary" data-copy="${GU({v:1})}" data-msg="QR link copied">${ic('link','sm')}Copy QR Link</button></div></div></div>`;
  if(p==='ordering'){const none=!S.tables.length;body=`${UI.tabs([{key:'dine',label:'Dine-In'},{key:'dp',label:'Delivery & Pick Up'}],'dine','qro')}
    ${UI.panel('qro','dine',`<div style="max-width:960px">${h3('QR Codes for Taking Orders','Guests scan these to order from their table. Each order arrives tagged with the table it came from.')}
     ${none?`<div class="card pad" style="background:var(--warn-tint);color:var(--warn);display:flex;gap:10px;align-items:center;margin-bottom:16px">${ic('warn')}<span>You don't have any tables yet. To create table QR codes, go to <a href="#settings-operations--tables">Tables</a>.</span></div>`:''}
     <div class="grid g2"><div class="card pad"><span class="itile" style="margin-bottom:10px">${ic('blocks')}</span><h3>Unique QR Code for each table</h3><p class="muted">Every table gets its own code, so you always know where an order came from. Best for table service.</p><button class="btn primary" data-action="set-qr-all" ${none?'disabled':''}>${ic('download','sm')}Download Table QR Codes</button></div>
     <div class="card pad"><span class="itile" style="margin-bottom:10px">${ic('qr')}</span><h3>One QR Code for all tables</h3><p class="muted">A single code for the whole venue. Guests pick their table number when they order.</p><button class="btn secondary" data-action="set-qr-single">${ic('download','sm')}Download Single QR Code</button></div></div></div>`,'dine')}
    ${UI.panel('qro','dp',`<div class="grid g2" style="max-width:960px">${['Delivery','Pick Up'].map(k=>`<div class="card pad" style="text-align:center"><h3>${k} QR Code</h3><p class="muted">Print on flyers, bags and receipts so guests can order ${k.toLowerCase()} directly.</p>${qrc('dp-'+k,160)}<div style="display:flex;gap:8px;justify-content:center;margin-top:12px"><button class="btn primary sm" data-action="download">${ic('download','sm')}Download</button><button class="btn secondary sm" data-copy="${GU({o:k==='Delivery'?'delivery':'pickup'})}">${ic('copy','sm')}Copy Link</button></div></div>`).join('')}</div>`,'dine')}`}
  if(p==='tablet')body=`<div class="form-card" style="display:grid;grid-template-columns:1fr 240px;gap:24px;align-items:start"><div>${F('Venue ID',`<div style="display:flex;gap:8px">${UI.input({value:S.venue.id,attrs:'readonly'})}<button class="btn secondary" data-copy="${S.venue.id}" data-msg="Venue ID copied">${ic('copy','sm')}</button></div>`)}
    ${F('Pincode',`<div style="display:flex;gap:8px">${inp('tabletPin',S.venue.pincode||'4821','',{attrs:'id="tabPin" maxlength="4" inputmode="numeric"'})}<button class="btn secondary" data-action="set-pin-gen" data-t="tabPin">Generate</button></div>`,{help:'4-digit pincode used to sign in to the tablet app.'})}${saveBtn()}</div>
    <div style="text-align:center">${F('QR Code',qrc('tablet-'+S.venue.id,200),{help:'Scan this with a tablet to open the menu.'})}</div></div>`;
  return frame('QR Codes',rTabs('settings-qr',QT,p),body)},{nav:'settings'});
A('qr-color',()=>{const fg=$('#view [data-k="qr.fg"]').value,bg=$('#view [data-k="qr.bg"]').value;const b=$('#qrPrev');b.style.background=bg;b.innerHTML=qrc('menu-display',200,fg,bg)});
A('qr-single',()=>App.modal({title:'Single QR Code',body:`${qrc('single-'+S.venue.id,220)}<p class="muted" style="text-align:center">${GU({})}</p>`,footer:`<button class="btn secondary" data-copy="${GU({})}">${ic('copy','sm')}Copy Link</button><button class="btn primary" data-action="download">${ic('download','sm')}Download</button>`}));

/* ---------- Design & Display ---------- */
const DT=[['qr','QR Menu'],['tablet','Tablet Menu']];
const PALETTES=[['Proview Blue','#1A2330','#FFFFFF','#1565C0'],['Classic Black','#111111','#FFFFFF','#111111'],['Warm Terracotta','#3B2A22','#FBF6F1','#C0623F'],['Deep Green','#1E2B24','#F4F7F2','#2E6B4F'],['Night Mode','#F1F3F6','#14181F','#4F8EF7'],['Mediterranean','#1B2B3A','#F7FAFC','#0E7490'],['Rose','#3A2430','#FFF7F9','#BE3A6B'],['Golden','#2B2416','#FFFCF5','#B7791F']];
App.route('settings-design',p=>{p=p||'qr';let left='';
  if(p==='qr')left=`<div class="card pad ai-border" style="display:flex;gap:12px;align-items:center;margin-bottom:16px"><span class="itile">${ic('palette')}</span><div style="flex:1"><strong style="color:var(--ink)">Set your QR menu colors</strong><div class="help" style="margin:2px 0 0">Start from a ready-made palette, then fine-tune each colour.</div></div><button class="btn primary" data-action="set-palettes">Choose colors</button></div>
   <div class="form-card" style="max-width:none">${h3('Theme Colors')}<div class="grid g3" style="gap:0 16px">${F('Text Color',color('dz.text','#1A2330','data-input="set-dz"'))}${F('Background Color',color('dz.bg','#FFFFFF','data-input="set-dz"'))}${F('Highlight Color',color('dz.hl','#1565C0','data-input="set-dz"'))}</div>
   <div class="grid g2" style="gap:0 16px">${F('Menu Background Image',UI.upload({label:'Upload',hint:'Portrait 9:16, under 10MB'}))}${F('Custom Font',UI.upload({label:'Upload font',hint:'.ttf or .otf',accept:'.ttf,.otf'}))}</div>
   <hr style="border:0;border-top:1px solid var(--border);margin:8px 0 16px">${h3('Menu Layout')}${F('Select Style',rc('dz.style',[{value:'list',label:'List View',text:'Shows more detail up front, such as descriptions and allergen warnings'},{value:'grid',label:'Grid View',text:'Fits more items on screen with less detail'}],'list','data-change="set-dz"'))}
   ${UI.toggleRow('Display section folders','Group sections into folders on the menu home.',v('dz.folders',false),'data-k="dz.folders" data-change="set-dz"')}
   ${F('Select Section Title Style',rc('dz.title',[{value:'both',label:'Titles with Images'},{value:'img',label:'Only Images'},{value:'txt',label:'Only Titles'}],'both','data-change="set-dz"'))}
   ${UI.toggleRow('Display Search & Filter','',v('dz.search',true),'data-k="dz.search" data-change="set-dz"')}${UI.toggleRow('Display Venue Info Button','',v('dz.info',true),'data-k="dz.info" data-change="set-dz"')}
   <hr style="border:0;border-top:1px solid var(--border);margin:8px 0 16px">${h3('Calorie Options')}${F('Calorie Unit',sel('dz.cal',['cal','kcal','kJ'],'cal'))}${UI.toggleRow('Display Estimated Walking Time','Show how long a walk it takes to burn each item off.',v('dz.walk',false),'data-k="dz.walk"')}
   <hr style="border:0;border-top:1px solid var(--border);margin:8px 0 16px">${h3('Ingredient / Allergen Warnings')}${UI.toggleRow('Display ingredient warning labels','',v('dz.warn',true),'data-k="dz.warn" data-change="set-dz"')}${F('Ingredient label text size',sel('dz.wsize',['Small','Regular','Large'],'Regular'))}
   <hr style="border:0;border-top:1px solid var(--border);margin:8px 0 16px">${h3('Discoverability')}${UI.toggleRow('Index Menu on Search Engine','Let Google and other search engines list your menu page.',v('dz.index',true),'data-k="dz.index"')}${saveBtn()}</div>`;
  if(p==='tablet'){const themes=v('themes',[{name:'Standard Theme',active:true},{name:'New Year 2023',active:false}]);left=`<div class="form-card" style="max-width:none">
   ${F('Screen Orientation',radios('tb.orient',['Portrait','Landscape'],'Landscape','data-change="set-dz"'))}
   ${F('Menu Structure',rc('tb.struct',[{value:'Infinite Scroll',label:'Infinite Scroll',text:'One long page; sections follow each other'},{value:'Classic',label:'Classic',text:'Pick a section, then see its items'},{value:'Paper Menu',label:'Paper Menu',text:'Page-turning layout like a printed menu'}],'Infinite Scroll'))}
   <div style="display:flex;align-items:center;margin:8px 0 10px"><h3>Choose Theme</h3><button class="btn secondary sm" style="margin-left:auto" data-action="set-theme-add">${ic('plus','sm')}Add New Theme</button></div>
   <div class="grid g2" style="margin-bottom:16px">${themes.map((t,i)=>`<div class="card pad" style="${t.active?'border-color:var(--brand-700);background:var(--brand-tint-subtle)':''}"><div class="thumbbg" style="height:90px;border-radius:10px;margin-bottom:10px;${t.c?`--c1:${t.c};--c2:${t.c}`:''}"></div><div style="display:flex;align-items:center;gap:8px"><strong style="color:var(--ink)">${esc(t.name)}</strong>${UI.pill(t.active?'Active':'Inactive',t.active?'ok':'grey')}${t.active?'':`<button class="btn ghost sm" style="margin-left:auto" data-action="set-theme-on" data-i="${i}">Activate</button>`}</div></div>`).join('')}</div>
   ${h3('Calorie Options')}${F('Calorie Unit',sel('tb.cal',['cal','kcal','kJ'],'cal'))}${UI.toggleRow('Display total calories','Show the running calorie total in the basket.',v('tb.totcal',false),'data-k="tb.totcal"')}
   ${trow('tb.return','Enable Return to Homepage','Go back to the home screen after a period with no taps.',false,F('Seconds before returning',inp('tb.secs','60','',{type:'number',suffix:'secs'})))}
   ${h3('Ingredient / Allergen Warnings')}${UI.toggleRow('Display ingredient warning labels','',v('tb.warn',true),'data-k="tb.warn"')}${F('Ingredient label text size',sel('tb.wsize',['Small','Regular','Large'],'Regular'))}${saveBtn()}</div>`}
  return frame('Design & Display',rTabs('settings-design',DT,p),`<div style="display:grid;grid-template-columns:minmax(0,1fr) 330px;gap:24px;align-items:start"><div>${left}</div><div style="position:sticky;top:88px"><div class="eyebrow" style="display:flex;align-items:center;gap:6px;margin-bottom:10px">${ic('phone','sm')}Preview</div><div id="dzPhone">${p==='qr'?phone():tabletPrev()}</div></div></div>`)},{nav:'settings'});
function cur(k,d){const el=$(`#view [data-k="${k}"]`+(document.querySelector(`#view input[type=radio][data-k="${k}"]`)?':checked':''));if(!el)return v(k,d);return el.type==='checkbox'?el.checked:el.value}
function phone(){const tx=cur('dz.text','#1A2330'),bg=cur('dz.bg','#FFFFFF'),hl=cur('dz.hl','#1565C0'),grid=cur('dz.style','list')==='grid',ts=cur('dz.title','both'),search=cur('dz.search',true),info=cur('dz.info',true),warn=cur('dz.warn',true);
  const m=S.menus[0],secs=m.sections.slice(0,6),items=m.sections[0].items.filter(i=>i.on).slice(0,6);
  return `<div class="phone" style="width:290px;height:580px;background:${bg};color:${tx}"><div style="padding:18px 14px 10px;display:flex;align-items:center;gap:8px;border-bottom:1px solid rgba(0,0,0,.08)">${ic('left','sm')}<strong style="flex:1;text-align:center">${esc(S.venue.name)}</strong>${info?ic('info','sm'):''}</div>
   <div style="padding:10px 12px;overflow:auto;flex:1"><div style="font-weight:700;font-size:15px;margin-bottom:8px">${esc(m.name)}</div>
   ${search?`<div style="display:flex;gap:6px;align-items:center;border:1px solid rgba(0,0,0,.15);border-radius:10px;padding:7px 10px;font-size:12px;opacity:.8;margin-bottom:10px">${ic('search','sm')}Search<span style="margin-left:auto">${ic('filter','sm')}</span></div>`:''}
   <div style="display:flex;gap:8px;overflow:hidden;margin-bottom:12px">${secs.map((s,i)=>`<div style="flex:none;width:${ts==='txt'?'auto':'72px'};text-align:center">${ts!=='txt'?`<div class="thumbbg" style="height:56px;border-radius:10px;--c1:${hl};--c2:${hl}99;${i?'opacity:.75':''}"></div>`:''}${ts!=='img'?`<div style="font-size:10px;font-weight:600;margin-top:4px;${ts==='txt'?`padding:5px 10px;border-radius:99px;border:1px solid ${i?'rgba(0,0,0,.15)':hl};color:${i?tx:hl}`:''};white-space:nowrap;overflow:hidden;text-overflow:ellipsis">${esc(s.name)}</div>`:''}</div>`).join('')}</div>
   <div style="${grid?'display:grid;grid-template-columns:1fr 1fr;gap:8px':''}">${items.map(i=>grid?`<div style="border:1px solid rgba(0,0,0,.08);border-radius:10px;overflow:hidden"><div class="thumbbg" style="height:70px;--c1:${hl};--c2:${hl}88"></div><div style="padding:6px;font-size:11px"><b style="display:block;line-height:13px">${esc(i.name)}</b><span style="color:${hl};font-weight:700">£${i.price.toFixed(2)}</span></div></div>`:`<div style="display:flex;gap:10px;padding:9px 0;border-bottom:1px solid rgba(0,0,0,.07)"><div style="flex:1;min-width:0"><b style="font-size:12px;display:block">${esc(i.name)}</b><small style="font-size:10px;opacity:.7;display:block;line-height:13px">${esc(i.desc)}</small>${warn?`<small style="font-size:9px;display:inline-block;margin-top:3px;padding:1px 6px;border-radius:99px;background:${hl}22;color:${hl}">Contains gluten</small>`:''}<div style="color:${hl};font-weight:700;font-size:12px;margin-top:3px">£${i.price.toFixed(2)}</div></div><div class="thumbbg" style="width:52px;height:52px;border-radius:8px;--c1:${hl};--c2:${hl}88"></div></div>`).join('')}</div></div></div>`}
function tabletPrev(){const land=cur('tb.orient','Landscape')==='Landscape';const m=S.menus[0];return `<div style="width:${land?300:220}px;height:${land?210:300}px;border:9px solid #1A2330;border-radius:18px;background:#fff;margin:0 auto;overflow:hidden;display:flex"><div style="width:30%;background:var(--brand-tint-subtle);padding:8px;font-size:9px;line-height:16px;color:var(--ink)">${m.sections.slice(0,8).map((s,i)=>`<div style="${i?'':'font-weight:700;color:var(--brand-700)'}">${esc(s.name)}</div>`).join('')}</div><div style="flex:1;padding:8px;display:grid;grid-template-columns:1fr 1fr;gap:6px;align-content:start">${m.sections[0].items.slice(0,land?4:6).map(i=>`<div style="border:1px solid var(--border);border-radius:6px;overflow:hidden"><div class="thumbbg" style="height:${land?44:34}px"></div><div style="font-size:8px;padding:3px;font-weight:600;color:var(--ink)">${esc(i.name)}</div></div>`).join('')}</div></div>`}
A('dz',()=>{const ph=$('#dzPhone');if(!ph)return;ph.innerHTML=App.current().includes('tablet')?tabletPrev():phone()});
A('palettes',()=>App.modal({title:'Choose colors',wide:true,body:`<div class="grid g4" style="gap:12px">${PALETTES.map(([n,t,b,h],i)=>`<button class="select-card" data-action="set-palette" data-i="${i}"><div style="display:flex;gap:6px;margin-bottom:10px"><span class="swatch" style="background:${t}"></span><span class="swatch" style="background:${b}"></span><span class="swatch" style="background:${h}"></span></div><strong style="color:var(--ink)">${n}</strong></button>`).join('')}</div>`}));
A('palette',el=>{const [,t,b,h]=PALETTES[+el.dataset.i];[['dz.text',t],['dz.bg',b],['dz.hl',h]].forEach(([k,c])=>{const i=$(`#view [data-k="${k}"]`);if(i){i.value=c;const x=$(`[data-hex="${k}"]`);if(x)x.textContent=c}});App.closeModal();App.actions['set-dz']();App.toast('Palette applied – press Save to keep it')});
A('theme-add',()=>App.modal({title:'Add New Theme',body:F('Theme Name',UI.input({id:'thName',placeholder:'e.g. Summer 2027'}),{required:true})+F('Main Color',`<input type="color" id="thColor" value="#1565C0" style="width:60px;height:40px;border:1px solid var(--border-input);border-radius:8px">`)+F('Background Image',UI.upload({label:'Upload',hint:'Landscape 16:9, under 10MB'})),footer:`<button class="btn secondary" data-close>Cancel</button><button class="btn primary" data-action="set-theme-save">Create</button>`}));
A('theme-save',()=>{const n=$('#thName').value.trim();if(!n)return App.toast('Enter a theme name');const th=v('themes',[{name:'Standard Theme',active:true},{name:'New Year 2023',active:false}]);th.push({name:n,active:false,c:$('#thColor').value});S.cfg.themes=th;App.closeModal();App.render();App.toast('Theme added')});
A('theme-on',el=>{const th=v('themes',[{name:'Standard Theme',active:true},{name:'New Year 2023',active:false}]);th.forEach((t,i)=>t.active=i===+el.dataset.i);S.cfg.themes=th;App.render();App.toast(th[+el.dataset.i].name+' is now active')});

/* ---------- Welcome Page ---------- */
const WT=[['dinein','Dine-in QR'],['delivery','Delivery & Pick Up'],['tablet','Tablet']];
App.route('settings-welcome',p=>{p=p||'dinein';const k=x=>`wp.${p}.${x}`;
  const body=`<div style="display:grid;grid-template-columns:minmax(0,1fr) 300px;gap:24px;align-items:start"><div class="form-card" style="max-width:none">
   ${trow(k('show'),'Display Welcome Page','Greet guests with your venue details before they open the menu.',true,'',`<a href="#" data-action="set-wp-what" style="font-size:13px">What is Welcome Page?</a>`)}
   ${UI.toggleRow('Display Venue Name','',v(k('name'),true),`data-k="${k('name')}"`)}
   ${trow(k('msg'),'Welcome Message','Add a short greeting under your venue name.',true,inp(k('msgText'),'Welcome to '+S.venue.name+'! Scan, browse and order from your table.','Welcome message'))}
   ${trow(k('landing'),'Enable Custom Landing Page'+newTag,'Open with your own photo or video and a single button before the welcome page.',false,
     `<div class="grid g2" style="gap:12px">${F('Image',UI.upload({label:'Upload image',hint:'Portrait 9:16, under 10MB'}))}${F('Video',UI.upload({label:'Upload video',hint:'.mp4, portrait 9:16, under 50MB. The image is used as the poster.',accept:'.mp4'}))}</div>
      ${trow(k('btn'),'Display Text Button','',true,g2(F('Welcome Button Text',inp(k('btnText'),'View Menu')),F('Text Color',color(k('btnColor'),'#FFFFFF'))))}`,`<a href="#" data-action="set-wp-landing" style="font-size:13px">What is Custom Landing Page?</a>`)}
   ${trow(k('social'),'Display Social Media Icons','Uses the links from Venue Information › Social Accounts.',true,F('Icon Color',color(k('iconColor'),'#1565C0')))}
   ${trow(k('lang'),'Display Language Options','',true,g2(F('Language Options Position',sel(k('langPos'),['Top Left','Top Right','Middle'],'Top Right')),F('Language Options Text Color',color(k('langColor'),'#1A2330'))))}
   ${saveBtn()}</div>
   <div class="card pad" id="wpNews" style="position:sticky;top:88px;background:var(--brand-tint-subtle)"><div style="display:flex;align-items:center;gap:8px"><span style="font-size:18px">💡</span><strong style="color:var(--ink)">What's New</strong><button class="iconbtn" style="margin-left:auto;width:28px;height:28px;border:0;background:none" onclick="this.closest('#wpNews').remove()" aria-label="Dismiss">${ic('x','sm')}</button></div><div class="thumbbg" style="height:120px;border-radius:10px;margin:12px 0"></div><h3>New Welcome Page!</h3><p class="muted" style="margin:6px 0 12px">Show your welcome page and greet guests with a branded start: your logo, opening hours, contact details and links.</p><button class="btn secondary sm" data-action="set-wp-what">More Detail</button></div></div>`;
  return frame('Welcome Page',rTabs('settings-welcome',WT,p),body,{tutorial:true})},{nav:'settings'});
A('wp-what',(el,e)=>{e.preventDefault();App.modal({title:'What is Welcome Page?',body:`<div class="thumbbg" style="height:160px;border-radius:12px;margin-bottom:12px"></div><p style="margin:0">The welcome page is the first screen guests see after scanning your QR code. It shows your logo, venue name, a short message, opening hours, social links and a language picker, then a button to open the menu.</p>`,footer:'<button class="btn primary" data-close>Got it</button>'})});
A('wp-landing',(el,e)=>{e.preventDefault();App.modal({title:'What is Custom Landing Page?',body:`<p style="margin:0">A full-screen photo or video with one button, shown before your welcome page. Use it for a seasonal campaign, a new dish, or simply to set the mood.</p>`,footer:'<button class="btn primary" data-close>Got it</button>'})});

/* ---------- Operating Hours ---------- */
const HT=[['dinein','Dine-in QR'],['delivery','Delivery & Pick Up']];
App.route('settings-hours',p=>{p=p||'dinein';const days=['Monday','Tuesday','Wednesday','Thursday','Friday','Saturday','Sunday'];
  return frame('Operating Hours',rTabs('settings-hours',HT,p),`<div class="form-card"><p class="muted" style="margin-top:0">Guests can only order ${p==='dinein'?'from the dine-in QR menu':'delivery and pick-up'} during these hours.</p><div class="days">${days.map(d=>`<div class="day" style="grid-template-columns:150px 1fr 20px 1fr">${ck(`hrs.${p}.${d}.on`,`<strong style="color:var(--ink)">${d}</strong>`,true)}<div class="input-group"><input type="time" value="${v(`hrs.${p}.${d}.open`,'00:00')}" data-k="hrs.${p}.${d}.open" aria-label="${d} opens"><span class="after">${ic('clock','sm')}</span></div><span style="text-align:center">–</span><div class="input-group"><input type="time" value="${v(`hrs.${p}.${d}.close`,'23:59')}" data-k="hrs.${p}.${d}.close" aria-label="${d} closes"><span class="after">${ic('clock','sm')}</span></div></div>`).join('')}</div>${saveBtn()}</div>`)},{nav:'settings'});

/* ---------- Price Options ---------- */
const PT=[['dinein','Dine In'],['tablet','Tablet']];
App.route('settings-price',p=>{p=p||'dinein';const k=x=>`pr.${p}.${x}`;const extra=v(k('extraList'),['AED','AUD','CAD','CHF','EUR','GBP','KWD','NZD','TRY','USD']);
  return frame('Price Options',rTabs('settings-price',PT,p),`<div class="form-card">${h3((p==='dinein'?'Dine-in':'Tablet')+' Price Option')}
   ${UI.toggleRow('Display prices','Show or hide prices on the menu.',v(k('show'),true),`data-k="${k('show')}"`)}
   ${UI.toggleRow('Display currency sign','e.g. £7.00 rather than 7.00',v(k('sign'),true),`data-k="${k('sign')}"`)}
   ${UI.toggleRow('Display currency fraction','Turn off to show 7 instead of 7.00',v(k('frac'),true),`data-k="${k('frac')}"`)}
   <div style="margin-top:16px">${F('Menu Currency',sel(k('cur'),CURR.map(([c,n])=>({value:c,label:n})),'GBP'))}</div>
   ${F(`Additional Currencies <span title="Guests can switch the menu to these currencies">${ic('info','sm')}</span>`,`<div style="display:flex;gap:14px;flex-wrap:wrap;align-items:center" id="curList">${extra.map(c=>c==='GBP'?UI.check(c,true,'disabled'):ck(k('x.'+c),c,false,'data-change="set-rates"')).join('')}<button class="btn ghost sm" data-action="set-cur-add" data-p="${p}">${ic('plus','sm')}Add</button></div>`)}
   ${trow(k('custom'),'Enable Custom Currency Rate','Set your own exchange rates instead of the daily rate.',false,`<div id="rateBox">${rateRows(p)}</div>`)}
   ${UI.toggleRow('Enable Display Multiple Currencies','Show prices in more than one currency at the same time.',v(k('multi'),false),`data-k="${k('multi')}"`)}${saveBtn()}</div>`)},{nav:'settings'});
function rateRows(p){const sel=$$(`#view [data-k^="pr.${p}.x."]`).filter(c=>c.checked).map(c=>c.dataset.k.split('.').pop());const list=sel.length||$('#view')?.querySelector('#curList')?sel:Object.keys(S.cfg).filter(x=>x.startsWith(`pr.${p}.x.`)&&S.cfg[x]).map(x=>x.split('.').pop());
  return list.length?list.map(c=>`<div style="display:flex;gap:10px;align-items:center;margin-bottom:8px"><span style="width:90px">1 GBP =</span>${UI.input({value:v(`pr.${p}.rate.${c}`,''),placeholder:'0.00',suffix:c,attrs:`data-k="pr.${p}.rate.${c}" inputmode="decimal"`})}</div>`).join(''):'<p class="muted" style="margin:0">Tick an additional currency above to set its rate.</p>'}
A('rates',()=>{const p=App.current().split('--')[1]||'dinein';const b=$('#rateBox');if(b)b.innerHTML=rateRows(p)});
A('cur-add',el=>{const p=el.dataset.p;const have=v(`pr.${p}.extraList`,['AED','AUD','CAD','CHF','EUR','GBP','KWD','NZD','TRY','USD']);App.modal({title:'Add Currency',body:F('Currency',UI.select(CURR.filter(([c])=>!have.includes(c)).map(([c,n])=>({value:c,label:`${c} – ${n}`})),'','id="curNew"')),footer:`<button class="btn secondary" data-close>Cancel</button><button class="btn primary" data-action="set-cur-save" data-p="${p}">Add</button>`})});
A('cur-save',el=>{const p=el.dataset.p;collect();const have=v(`pr.${p}.extraList`,['AED','AUD','CAD','CHF','EUR','GBP','KWD','NZD','TRY','USD']).slice();const c=$('#curNew').value;if(c&&!have.includes(c)){have.push(c);S.cfg[`pr.${p}.x.${c}`]=true}S.cfg[`pr.${p}.extraList`]=have;App.closeModal();App.render();App.toast(c+' added')});
})();
